distributed under the License is distributed on an "AS IS" BASIS, WITHOUT 
WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
********************************************************************************
* 
* Released: 2023-10-20
* 
* This is a Webex Device Macro which displays a video while 
* waiting in a Webex Calling call queue:
* 
* Features:
* 1. Supports multiple call queues & video content display
* 2. Can auto hide/unhide Call control UI in and out of call
* 
* Requirements:
* 1. Webex Device must be provisioned with a Webex Calling subscription
* 2. A call queue must be setup on control hub and its number added to the macro
* 3. Agents must be added to the call queue so the call can be answered
* 
* Full Readme and source code available on Github:
* https://github.com/wxsd-sales/video-queue-macro
* 
*
* Support:
* Please reach out to the WXSD team at wxsd@external.cisco.com
*******************************************************************************/
import xapi from 'xapi';

/*******************************************************************************
 * Configure the settings below - if needed
 ******************************************************************************/

const config = {
  queues: [                           // Array of queues to monitor and display commercials
    {
      number: '703659',
      mode: 'Fullscreen',
      target: 'OSD',
      title: 'Please wait ...',
      url: 'https://www.youtube-nocookie.com/embed/SliY6sT28nM?autoplay=1&loop=1&controls=0&disablekb=1&playlist=SliY6sT28nM'
    }
  ],
  hideUI: false,                      // true = hide out of call controls, false = show controls
  hideIncallUI: false,                // true = hide in call call controls, false = show controls
  panelIdPrefix: 'video-call-queue',  // Our Panel Id prefix for all speed dial buttons
}


/*******************************************************************************
 * Below contains all macros functions
 ******************************************************************************/

/*********************************************************
 * Below contains all macros functions
**********************************************************/

// Create our speed dial buttons
config.queues.forEach((queue, i) => createPanel(queue, i))

// Subscribe to Events & Status changes
xapi.Event.UserInterface.Extensions.Panel.Clicked.on(processClick)
xapi.Status.UserInterface.WebView.on(processWebView);
xapi.Status.Call['*'].Status.on(processCallsStatus);
xapi.Status.Call['*'].ghost.on(processCallsStatus);

function processCallsStatus() {
  // Get the active call on status change
  xapi.Status.Call.get().then(calls => calls?.[0]).then(call => {
    const queue = config.queues.find(queue => call?.CallbackNumber.endsWith(queue.number))
    // If call is disconnecting, hide any web view playing commercial
    if (call?.Status === 'Disconnecting' || call == null) {
      hideCommercial()
    }
    // If connecting call targets a queue, show commercial
    if (call?.Status === 'Connecting' && queue != null) {
      showCommercial(queue)
    }
  }).catch(e => console.error('Error processing call Status: ' + e.message))
}

function processClick(click) {
  // Ignore all button presses which don't begin with our panelIdPrefix
  if (!click.PanelId.startsWith(config.panelIdPrefix)) return;
  // Get index for the pressed panelId and match to our queues array.
  const index = click.PanelId.substr(config.panelIdPrefix.length);
  console.info(`Button [${config.queue[index]}] clicked`)
  // Dial the target associated with queue
  dial(config.queue[index].target)
}

function processWebView(webView) {
  // Extract the URL hash, if any
  const hash = webView?.URL?.match(/#\d+$/)?.[0]?.substr(1)
  // A very naive check to see if search param is present and set to true
  const isMacroEnabled = webView?.URL?.includes('isMacroEnabled=true')
  // Dial the target associated with hash
  isMacroEnabled
    && config.queues.find(queue => (queue.number === hash))
    && dial(hash)
}

function showCommercial({title, url, mode, target }) {
  console.info(`Opening Webview on [${target}] - Title: ${title} | Mode: ${mode} | Url: ${url}`)
  xapi.Command.UserInterface.WebView.Display(
    { Mode: mode, Target: target, Title: title, Url: url })
    .catch(e => console.error('Error opening webview: ' + e.message))
}

function hideCommercial() {
  console.info('Hiding Any Commerical')
  xapi.Command.UserInterface.WebView.Clear();
}

function setUIVisability(state){
  console.info('Setting UI Visability to: ' + state)
  xapi.Config.UserInterface.Features.HideAll.set(state ? 'False' : 'True');
}

function dial(number) {
  console.info(`Dialing number [${number}]`);
  xapi.Command.Dial({ Number: number })
  .catch(e=> console.error(`Unable to dial [${number}] - Error: ${e.message}`))
}

function createPanel(queue, i) {
  const panel = `
    <Extensions>
      <Panel>
        <Type>Statusbar</Type>
        <Location>HomeScreen</Location>
        <Icon>Helpdesk</Icon>
        <Color>#0000ff</Color>
        <Name>Help (${queue.number})</Name>
        <ActivityType>Custom</ActivityType>
      </Panel>
    </Extensions>`
  xapi.Command.UserInterface.Extensions.Panel.Save({ PanelId: config.panelIdPrefix + i },panel)
    .catch(e => console.error('Error saving panel: ' + e.message))
}"
}

